/* SWE Fundamentals Exam: single-file app, no dependencies.
 * Data: window.EXAM_DATA, generated by tools/parse_exam.py (questions.js).
 */
(() => {
  'use strict';

  const DATA = window.EXAM_DATA;
  const app = document.getElementById('app');
  if (!DATA) {
    app.innerHTML = '<p class="boot">Could not load questions.js. Run <code>python3 -I tools/parse_exam.py source/software-engineering-fundamentals-exam.md questions.json</code> to generate it.</p>';
    return;
  }

  const STORE_KEY = 'sweExam.session.v1';
  const HISTORY_KEY = 'sweExam.history.v1';
  const SESSION_VERSION = 1;
  const HISTORY_VERSION = 1;
  const P = Object.fromEntries(DATA.parts.map(p => [p.id, p]));
  const Q = Object.fromEntries(DATA.questions.map(q => [q.id, q]));

  /* ================================================================
   * Small utilities
   * ================================================================ */

  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const now = () => Date.now();
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

  function fmtClock(ms) {
    const total = Math.max(0, Math.ceil(ms / 1000));
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    const pad = n => String(n).padStart(2, '0');
    return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
  }
  function fmtMinutes(min) {
    if (min < 60) return `${min} min`;
    const h = Math.floor(min / 60), m = min % 60;
    return m ? `${h} h ${m} min` : `${h} h`;
  }
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many || one + 's'}`;

  /* Minimal, safe Markdown for exam prompts: fenced code, ordered and
   * bullet lists, paragraphs, `code`, **bold**, *italic*. All input is
   * escaped first; nothing from the data is ever inserted as raw HTML. */
  function inlineMd(src) {
    const codes = [];
    let s = src.replace(/`([^`]+)`/g, (_, c) => { codes.push(c); return '\u0000' + (codes.length - 1) + '\u0000'; });
    s = esc(s)
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/(^|[^*\w])\*([^*\s][^*]*?)\*(?![*\w])/g, '$1<em>$2</em>');
    return s.replace(/\u0000(\d+)\u0000/g, (_, i) => '<code>' + esc(codes[+i]) + '</code>');
  }
  function renderMd(text) {
    const lines = String(text || '').split('\n');
    const out = [];
    let para = [], list = null;
    const flushPara = () => { if (para.length) { out.push('<p>' + para.map(inlineMd).join(' ') + '</p>'); para = []; } };
    const flushList = () => { if (list) { out.push(`<${list.tag}>` + list.items.map(i => '<li>' + inlineMd(i) + '</li>').join('') + `</${list.tag}>`); list = null; } };
    for (let i = 0; i < lines.length; i++) {
      const ln = lines[i];
      const fence = ln.match(/^\s*```(\S*)\s*$/);
      if (fence) {
        flushPara(); flushList();
        const buf = [];
        i++;
        while (i < lines.length && !/^\s*```\s*$/.test(lines[i])) buf.push(lines[i++]);
        out.push('<pre><code' + (fence[1] ? ` data-lang="${esc(fence[1])}"` : '') + '>' + esc(buf.join('\n')) + '</code></pre>');
        continue;
      }
      if (!ln.trim()) { flushPara(); flushList(); continue; }
      const ol = ln.match(/^\s*\d+\.\s+(.*)$/);
      const ul = ln.match(/^\s*[-*]\s+(.*)$/);
      if (ol || ul) {
        flushPara();
        const tag = ol ? 'ol' : 'ul';
        if (!list || list.tag !== tag) { flushList(); list = { tag, items: [] }; }
        list.items.push((ol || ul)[1]);
        continue;
      }
      if (list && /^\s+\S/.test(ln)) { list.items[list.items.length - 1] += ' ' + ln.trim(); continue; }
      flushList();
      para.push(ln.trim());
    }
    flushPara(); flushList();
    return out.join('\n');
  }

  function announce(msg) {
    const live = document.getElementById('live');
    live.textContent = '';
    setTimeout(() => { live.textContent = msg; }, 50);
  }

  /* Promise-based confirm dialog on a native <dialog>. */
  function confirmDialog({ title, body, okLabel = 'OK', cancelLabel = 'Cancel', danger = false }) {
    const dlg = document.getElementById('dlg');
    if (!dlg || typeof dlg.showModal !== 'function') return Promise.resolve(window.confirm(title + '\n\n' + body.replace(/<[^>]+>/g, '')));
    $('#dlg-title').textContent = title;
    $('#dlg-body').innerHTML = body;
    const ok = $('#dlg-ok'), cancel = $('#dlg-cancel');
    ok.textContent = okLabel;
    cancel.textContent = cancelLabel;
    ok.className = 'btn ' + (danger ? 'danger' : 'primary');
    return new Promise(resolve => {
      const onClose = () => { dlg.removeEventListener('close', onClose); resolve(dlg.returnValue === 'ok'); };
      dlg.addEventListener('close', onClose);
      dlg.returnValue = 'cancel';
      dlg.showModal();
      cancel.focus();
    });
  }

  /* ================================================================
   * Storage (localStorage, with an in-memory fallback)
   * ================================================================ */

  let storageOk = true;
  let storageProblem = '';
  let memoryStore = null;
  function loadSession() {
    try {
      const raw = localStorage.getItem(STORE_KEY);
      storageOk = true;
      storageProblem = '';
      return raw ? JSON.parse(raw) : null;
    } catch (e) {
      storageOk = false;
      storageProblem = `Browser storage is unavailable: ${e.message}`;
      return memoryStore;
    }
  }

  function migrateSession(s) {
    if (!s || typeof s !== 'object') return s;
    if (!s.grades || typeof s.grades !== 'object') s.grades = {};
    if (!s.status) s.status = s.phase === 'submitted' ? 'grading' : 'in_progress';
    if (s.gradedAt === undefined) s.gradedAt = null;
    if (s.historySaved === undefined) s.historySaved = false;
    return s;
  }

  function writeSession(s) {
    memoryStore = s;
    try {
      if (s) localStorage.setItem(STORE_KEY, JSON.stringify(s));
      else localStorage.removeItem(STORE_KEY);
      storageOk = true;
      storageProblem = '';
    } catch (e) {
      storageOk = false;
      storageProblem = `Could not save this session in browser storage: ${e.message}`;
    }
  }

  let historyProblem = '';
  function readHistory() {
    try {
      const raw = localStorage.getItem(HISTORY_KEY);
      if (!raw) return [];
      const data = JSON.parse(raw);
      if (!data || data.formatVersion !== HISTORY_VERSION || !Array.isArray(data.attempts)) {
        throw new Error('The saved history has an unsupported or invalid format.');
      }
      if (!data.attempts.every(validHistoryAttempt)) {
        throw new Error('The saved history contains an invalid attempt record.');
      }
      historyProblem = '';
      return data.attempts;
    } catch (e) {
      historyProblem = `Could not read attempt history: ${e.message}`;
      return null;
    }
  }

  function writeHistory(attempts) {
    try {
      localStorage.setItem(HISTORY_KEY, JSON.stringify({ formatVersion: HISTORY_VERSION, attempts }));
      historyProblem = '';
      return true;
    } catch (e) {
      historyProblem = `Could not save attempt history: ${e.message}`;
      return false;
    }
  }

  function publicNav(active = '') {
    return `<nav class="site-nav" aria-label="Main navigation">
      <a href="#" class="site-link ${active === 'setup' ? 'current' : ''}" data-screen="setup" ${active === 'setup' ? 'aria-current="page"' : ''}>Setup</a>
      <a href="#" class="site-link ${active === 'history' ? 'current' : ''}" data-screen="history" ${active === 'history' ? 'aria-current="page"' : ''}>History</a>
      ${S && S.phase === 'submitted' && S.status !== 'graded' ? '<a href="#" class="site-link" data-screen="review">Return to grading</a>' : ''}
    </nav>`;
  }

  function bindPublicNav() {
    $$('[data-screen]').forEach(link => link.addEventListener('click', event => {
      event.preventDefault();
      if (link.dataset.screen === 'history') renderHistory();
      else if (link.dataset.screen === 'review') renderSubmitted();
      else if (S) abandonAttempt();
      else {
        S = null;
        writeSession(null);
        renderSetup();
      }
      window.scrollTo({ top: 0 });
    }));
  }

  /* ================================================================
   * Seeded shuffle (xmur3 hash -> mulberry32 PRNG -> Fisher-Yates)
   * Every shuffle derives its own stream from (seed, label), so the
   * same seed always reproduces the same order, whatever else changes.
   * ================================================================ */

  function xmur3(str) {
    let h = 1779033703 ^ str.length;
    for (let i = 0; i < str.length; i++) {
      h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
      h = (h << 13) | (h >>> 19);
    }
    return () => {
      h = Math.imul(h ^ (h >>> 16), 2246822507);
      h = Math.imul(h ^ (h >>> 13), 3266489909);
      return (h ^= h >>> 16) >>> 0;
    };
  }
  function mulberry32(a) {
    return () => {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const rngFor = (seed, label) => mulberry32(xmur3(seed + '|' + label)());
  function shuffled(arr, rng) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
  function newSeed() {
    const bytes = new Uint32Array(2);
    (window.crypto || window.msCrypto).getRandomValues(bytes);
    return (bytes[0].toString(36) + bytes[1].toString(36)).slice(0, 8).padEnd(8, '0');
  }

  /* Question order per part (shuffled within each section, sections stay
   * in order) and option order per multiple-choice question.
   * Pure function of (parts, seed): this is what makes a seed reproducible. */
  function buildOrders(partIds, seed) {
    const order = {}, optionOrder = {};
    for (const pid of partIds) {
      const part = P[pid];
      let ids = [];
      if (part.sections.length) {
        for (const sec of part.sections) ids = ids.concat(shuffled(sec.question_ids, rngFor(seed, `q:${pid}:${sec.id}`)));
      } else {
        ids = shuffled(DATA.questions.filter(q => q.part === pid).map(q => q.id), rngFor(seed, `q:${pid}`));
      }
      order[pid] = ids;
      for (const id of ids) {
        const q = Q[id];
        if (q.type !== 'multiple_choice') continue;
        const free = q.options.filter(o => !o.pinned).map(o => o.text);
        const pinned = q.options.filter(o => o.pinned).map(o => o.text);
        // Questions that point at options by letter are left in their original order.
        const keepOrder = q.flags.includes('refers_to_options_by_letter');
        optionOrder[id] = (keepOrder ? free : shuffled(free, rngFor(seed, `o:${id}`))).concat(pinned);
      }
    }
    return { order, optionOrder };
  }

  /* ================================================================
   * Session model
   * ================================================================ */

  let S = null;            // the live session (also mirrored in localStorage)
  let saveTimer = null;
  let announced = {};      // timer thresholds already announced for the current clock
  let ticks = 0;

  function newSession(partIds, mode, seed) {
    const { order, optionOrder } = buildOrders(partIds, seed);
    const t = now();
    const budget = partIds.reduce((n, id) => n + P[id].minutes, 0) * 60000;
    const s = {
      v: SESSION_VERSION,
      dataHash: DATA.meta.source_sha256,
      id: 'a' + t.toString(36) + '-' + seed,
      seed, mode, parts: partIds,
      order, optionOrder,
      answers: {}, grades: {}, flagged: {}, qpos: Object.fromEntries(partIds.map(id => [id, 0])),
      partState: Object.fromEntries(partIds.map(id => [id, { startedAt: null, deadline: null, endedAt: null, locked: false, spentMs: 0, endReason: null }])),
      cursor: { partIdx: 0 },
      phase: mode === 'total' ? 'active' : 'ready',   // ready | active | submitted
      status: 'in_progress', gradedAt: null, historySaved: false,
      startedAt: t, lastTick: t, submittedAt: null, submitReason: null,
      totalBudgetMs: budget, deadline: mode === 'total' ? t + budget : null,
      notice: null,
    };
    if (mode === 'total') for (const id of partIds) s.partState[id].startedAt = t;
    return s;
  }

  const curPartId = () => S.parts[S.cursor.partIdx];
  const curPS = () => S.partState[curPartId()];
  const partBudgetMs = pid => P[pid].minutes * 60000;
  const isAnswered = id => {
    const v = S.answers[id];
    return typeof v === 'string' && v.trim() !== '';
  };

  function save() {
    clearTimeout(saveTimer); saveTimer = null;
    if (!S) return;
    writeSession(S);
    const el = $('#savedat');
    if (el) el.textContent = storageProblem || ('saved ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
  }
  function saveSoon() { clearTimeout(saveTimer); saveTimer = setTimeout(save, 250); }

  /* ================================================================
   * Timers. Everything is based on absolute timestamps stored in the
   * session, so a refresh (or a closed tab) can never reset or pause
   * the clock. There is deliberately no pause control.
   * ================================================================ */

  function remainingMs() {
    if (S.phase !== 'active') return null;
    return S.mode === 'total' ? S.deadline - now() : curPS().deadline - now();
  }
  function budgetMs() {
    if (!S) return 0;
    return S.mode === 'total' ? S.totalBudgetMs : partBudgetMs(curPartId());
  }

  function tick() {
    if (!S) return;
    if (S.phase === 'active') {
      const t = now();
      const dt = Math.max(0, t - S.lastTick);
      S.lastTick = t;
      curPS().spentMs += dt;
      if (S.mode === 'total') {
        if (t >= S.deadline) { finishExam('time'); return; }
      } else if (t >= curPS().deadline) {
        endPart(S.cursor.partIdx, 'time'); return;
      }
      if (++ticks % 20 === 0) save();   // persist roughly every 5 s (4 ticks per second)
    }
    updateTimerUI();
  }

  function startPart() {                       // per-part mode: begin the clock for this part
    const ps = curPS(), t = now();
    ps.startedAt = t;
    ps.deadline = t + partBudgetMs(curPartId());
    S.phase = 'active'; S.lastTick = t; S.notice = null;
    announced = {};
    save(); render();
  }

  /* Lock a part. In per-part mode this moves on to the next part (or submits). */
  function endPart(idx, reason) {
    const pid = S.parts[idx], ps = S.partState[pid];
    if (ps.locked) return;
    ps.locked = true; ps.endedAt = now(); ps.endReason = reason;
    if (S.mode === 'perPart') ps.spentMs = Math.min(ps.spentMs, partBudgetMs(pid));
    if (idx >= S.parts.length - 1) { finishExam(reason === 'time' ? 'time' : 'manual'); return; }
    S.cursor.partIdx = idx + 1;
    S.phase = 'ready';
    S.notice = reason === 'time'
      ? `Time ran out for Part ${pid}. It is locked and your answers are saved.`
      : `Part ${pid} is finished and locked.`;
    announced = {};
    save(); render();
  }

  function finishExam(reason) {
    const t = now();
    for (const id of S.parts) {
      const ps = S.partState[id];
      if (!ps.locked) { ps.locked = true; ps.endedAt = t; ps.endReason = reason; }
      if (S.mode === 'perPart') ps.spentMs = Math.min(ps.spentMs, partBudgetMs(id));
    }
    if (S.mode === 'total') {            // trim any overshoot from a long absence to the budget
      let over = S.parts.reduce((n, id) => n + S.partState[id].spentMs, 0) - S.totalBudgetMs;
      for (const id of S.parts.slice().reverse()) {
        if (over <= 0) break;
        const cut = Math.min(over, S.partState[id].spentMs);
        S.partState[id].spentMs -= cut; over -= cut;
      }
    }
    S.phase = 'submitted'; S.submittedAt = t; S.submitReason = reason;
    S.status = 'grading';
    save(); render();
  }

  function updateTimerUI() {
    const box = $('.timer');
    if (!box || !S) return;
    const valEl = $('.timer-val', box), flagEl = $('.timer-flag', box), bar = $('.timebar i');
    const top = $('.topbar');
    const rem = remainingMs();
    if (rem === null) { valEl.textContent = fmtClock(budgetMs()); return; }
    const frac = Math.max(0, Math.min(1, rem / budgetMs()));
    valEl.textContent = fmtClock(rem);
    const state = frac <= 0.05 ? 'crit' : frac <= 0.2 ? 'warn' : '';
    box.classList.toggle('warn', state === 'warn');
    box.classList.toggle('crit', state === 'crit');
    top.classList.toggle('warn', state === 'warn');
    top.classList.toggle('crit', state === 'crit');
    flagEl.textContent = state === 'crit' ? 'under 5% left' : state === 'warn' ? 'under 20% left' : '';
    bar.style.transform = `scaleX(${frac})`;
    if (state === 'warn' && !announced.warn) { announced.warn = true; announce('Twenty percent of the time is left.'); }
    if (state === 'crit' && !announced.crit) { announced.crit = true; announce('Five percent of the time is left.'); }
  }

  /* ================================================================
   * Rendering
   * ================================================================ */

  function render() {
    if (!S) return renderSetup();
    if (S.phase === 'submitted') return renderSubmitted();
    if (S.phase === 'ready') return renderReady();
    return renderExam();
  }

  /* ---------- setup ---------- */

  function renderSetup(prefill = {}) {
    const checked = new Set(prefill.parts || ['A']);
    const mode = prefill.mode || 'perPart';
    const rules = DATA.meta.rules.filter(r => /closed book|grade honestly/i.test(r.label));
    app.innerHTML = `
      <div class="wrap">
        ${publicNav('setup')}
        <header class="hero">
          <p class="eyebrow">exam.sh</p>
          <h1>${esc(DATA.meta.title)}</h1>
          <p class="lede">A closed-book, self-graded exam. ${DATA.meta.total_points} points over ${DATA.parts.length} parts, about ${fmtMinutes(DATA.meta.total_minutes)} of working time. Pick the parts you want to sit today.</p>
        </header>

        <div class="rules">
          <strong>Ground rules.</strong>
          <ul>
            <li><strong>Closed book.</strong> No AI, no search, no notes. That is why there is no pause button.</li>
            <li>Refreshing or closing the tab does <strong>not</strong> stop the clock. Your answers and the deadline are saved in this browser.</li>
            <li>Only multiple choice is graded automatically. Everything else you grade yourself afterwards, so be honest.</li>
          </ul>
        </div>

        ${storageOk ? '' : `<p class="notice">${esc(storageProblem || 'This browser is blocking local storage, so a refresh will lose your progress.')}</p>`}

        <h2 class="section-title">1 · Parts</h2>
        <div class="selbar">
          <button type="button" class="btn small" id="sel-all">Select all</button>
          <button type="button" class="btn small" id="sel-none">Select none</button>
          <span class="sel-divider" aria-hidden="true"></span>
          <button type="button" class="btn small sitting" data-parts="A,B,C">Sitting 1: A-C</button>
          <button type="button" class="btn small sitting" data-parts="D,E">Sitting 2: D-E</button>
          <button type="button" class="btn small sitting" data-parts="F,G,H">Sitting 3: F-H</button>
          <button type="button" class="btn small sitting" data-parts="I,J">Sitting 4: I-J</button>
        </div>
        <ul class="parts" id="parts">
          ${DATA.parts.map(p => `
            <li class="part-row"><label>
              <input type="checkbox" name="part" value="${p.id}" ${checked.has(p.id) ? 'checked' : ''}>
              <span class="part-id" aria-hidden="true">${p.id}</span>
              <span><span class="part-name">Part ${p.id}: ${esc(p.name)}</span>${p.tests.toLowerCase() === p.name.toLowerCase() ? '' : `<span class="part-tests">${esc(p.tests)}</span>`}</span>
              <span class="part-meta">${plural(p.question_count, 'question')}<br>${p.points} pts · ${fmtMinutes(p.minutes)}</span>
            </label></li>`).join('')}
        </ul>

        <h2 class="section-title">2 · Timer</h2>
        <div class="modes" role="radiogroup" aria-label="Timer mode">
          <label class="mode"><input type="radio" name="mode" value="perPart" ${mode === 'perPart' ? 'checked' : ''}><b>Per-part timer</b>
            <span>Each part gets its own budget from the exam. The clock starts when you start that part. When it ends the part locks and you move on. No going back.</span></label>
          <label class="mode"><input type="radio" name="mode" value="total" ${mode === 'total' ? 'checked' : ''}><b>One total timer</b>
            <span>One clock for everything you selected (the sum of the budgets). Move between parts freely and spend the time how you like.</span></label>
        </div>

        <details class="adv">
          <summary>Advanced: shuffle seed</summary>
          <p>Every attempt gets a random seed that decides question and option order. Enter an old seed to get the same order again.</p>
          <label class="sr-only" for="seed">Shuffle seed</label>
          <input id="seed" type="text" autocomplete="off" spellcheck="false" placeholder="leave empty for a random seed" value="${esc(prefill.seed || '')}">
        </details>

        <div class="startbar"><div class="inner">
          <div class="totals" id="totals" aria-live="polite"></div>
          <button type="button" class="btn primary" id="start">Start exam</button>
        </div></div>

      </div>`;

    const boxes = () => $$('input[name=part]');
    const selected = () => boxes().filter(b => b.checked).map(b => b.value);
    const updateTotals = () => {
      const ids = selected();
      const pts = ids.reduce((n, id) => n + P[id].points, 0);
      const qs = ids.reduce((n, id) => n + P[id].question_count, 0);
      const min = ids.reduce((n, id) => n + P[id].minutes, 0);
      $('#totals').innerHTML = ids.length
        ? `<b>${plural(ids.length, 'part')}</b> · ${plural(qs, 'question')} · <b>${pts} pts</b> · <b>${fmtMinutes(min)}</b>`
        : 'Nothing selected';
      $('#start').disabled = ids.length === 0;
    };
    boxes().forEach(b => b.addEventListener('change', updateTotals));
    $('#sel-all').addEventListener('click', () => { boxes().forEach(b => (b.checked = true)); updateTotals(); });
    $('#sel-none').addEventListener('click', () => { boxes().forEach(b => (b.checked = false)); updateTotals(); });
    $$('.sitting').forEach(button => button.addEventListener('click', () => {
      const chosen = new Set(button.dataset.parts.split(','));
      boxes().forEach(box => { box.checked = chosen.has(box.value); });
      updateTotals();
    }));
    $('#start').addEventListener('click', () => {
      const ids = selected();
      if (!ids.length) return;
      const m = $('input[name=mode]:checked').value;
      const seed = $('#seed').value.trim() || newSeed();
      S = newSession(DATA.parts.map(p => p.id).filter(id => ids.includes(id)), m, seed);
      announced = {};
      save(); render();
    });
    bindPublicNav();
    updateTotals();
  }

  /* ---------- shared exam header ---------- */

  function headerHtml(ctxTitle, ctxSub, timerLabel, showAbandon) {
    return `
      <div class="topbar">
        <div class="wrap">
          <div class="ctx"><b>${esc(ctxTitle)}</b>${esc(ctxSub)}</div>
          <div class="timer" role="timer" aria-label="Time remaining">
            <span class="timer-label">${esc(timerLabel)}</span>
            <span class="timer-val">--:--</span>
            <span class="timer-flag"></span>
          </div>
        </div>
        <div class="timebar" aria-hidden="true"><i></i></div>
      </div>`;
  }

  function partBarHtml() {
    const items = S.parts.map((id, i) => {
      const ps = S.partState[id];
      const current = i === S.cursor.partIdx;
      if (S.mode === 'total' && S.phase === 'active') {
        return `<button type="button" class="ptab" data-part="${i}" ${current ? 'aria-current="true"' : ''}>Part ${id}</button>`;
      }
      return `<span class="ptab ${ps.locked ? 'done' : ''}" ${current ? 'aria-current="true"' : ''}>Part ${id}${ps.locked ? '<span class="sr-only"> (finished)</span>' : ''}</span>`;
    }).join('');
    const hint = S.mode === 'total' ? 'one clock · switch parts any time' : 'per-part clocks · locked parts stay locked';
    return `<div class="partbar"><div class="wrap">${items}<span class="hint">${hint}</span></div></div>`;
  }

  /* ---------- between parts (per-part mode) ---------- */

  function renderReady() {
    const pid = curPartId(), p = P[pid];
    const first = S.cursor.partIdx === 0;
    const done = S.parts.filter(id => S.partState[id].locked);
    app.innerHTML = `
      ${headerHtml('Part ' + pid, p.name, 'Budget', false)}
      ${partBarHtml()}
      <div class="wrap">
        <div class="card">
          ${S.notice ? `<p class="notice">${esc(S.notice)}</p>` : ''}
          <p class="eyebrow">${first ? 'ready?' : 'next up'}</p>
          <h1>Part ${pid}: ${esc(p.name)}</h1>
          <p class="meta-line">${plural(p.question_count, 'question')} · ${p.points} pts · ${fmtMinutes(p.minutes)} on the clock</p>
          <p>${esc(p.tests)}. The clock for this part starts the moment you press the button, and it cannot be paused. Refreshing the page will not reset it.</p>
          ${done.length ? `<p class="meta-line">Locked so far: ${done.map(id => 'Part ' + id).join(', ')}</p>` : ''}
          <div class="actions">
            <button type="button" class="btn primary" id="start-part">Start Part ${pid}</button>
            <span class="spacer"></span>
            <button type="button" class="linkish" id="abandon">Abandon this attempt</button>
          </div>
        </div>
      </div>`;
    updateTimerUI();
    $('#start-part').addEventListener('click', startPart);
    $('#abandon').addEventListener('click', abandonAttempt);
    $('#start-part').focus();
  }

  /* ---------- the exam itself ---------- */

  const isCodeType = q => ['coding', 'code_trace', 'system_design'].includes(q.type);
  const TYPE_LABEL = { multiple_choice: 'multiple choice', short_answer: 'short answer', code_trace: 'trace and predict', coding: 'coding', system_design: 'system design', judgment: 'judgment' };

  function renderExam(opts = {}) {
    const pid = curPartId(), part = P[pid], ids = S.order[pid];
    const qi = Math.min(S.qpos[pid] || 0, ids.length - 1);
    const q = Q[ids[qi]];
    const sec = q.section ? part.sections.find(s => s.id === q.section) : null;
    const lastPart = S.cursor.partIdx === S.parts.length - 1;
    const timerLabel = S.mode === 'total' ? 'Total left' : `Part ${pid} left`;

    let answerHtml;
    if (q.type === 'multiple_choice') {
      const order = S.optionOrder[q.id];
      answerHtml = `<fieldset class="opts"><legend class="sr-only">Choose one answer</legend>${order.map((text, i) => `
        <label class="opt"><input type="radio" name="opt" value="${i}" ${S.answers[q.id] === text ? 'checked' : ''}>
          <span class="letter" aria-hidden="true">${'ABCD'[i]}</span><span>${inlineMd(text)}</span></label>`).join('')}
      </fieldset>`;
    } else {
      const code = isCodeType(q);
      answerHtml = `
        <label class="qlabel" for="ans">Your answer</label>
        <textarea id="ans" class="ans ${code ? 'code' : ''}" spellcheck="${code ? 'false' : 'true'}" autocomplete="off" autocapitalize="off" ${code ? 'wrap="off"' : ''}></textarea>
        <div class="anshint"><span>${code ? 'Tab inserts spaces. Press Esc, then Tab, to move focus out of the box.' : 'Write in full sentences. Precision beats length.'}</span><span id="count"></span></div>`;
    }

    const navBtns = ids.map((id, i) => `<button type="button" class="qn" data-i="${i}" aria-label="" ${i === qi ? 'aria-current="true"' : ''}>${i + 1}</button>`).join('');
    const answeredN = ids.filter(isAnswered).length;
    const finishLabel = S.mode === 'total' ? 'Submit exam' : lastPart ? 'Finish and submit' : `Finish Part ${pid}`;

    app.innerHTML = `
      ${headerHtml(`Part ${pid}: ${part.name}`, `question ${qi + 1} of ${ids.length}`, timerLabel)}
      ${partBarHtml()}
      <main class="wrap exam-main" id="main">
        <nav class="qnav" aria-label="Questions in this part">${navBtns}</nav>
        <p class="legend"><span id="progress">${answeredN} of ${ids.length} answered</span> · filled = answered · corner mark = flagged for review</p>
        <article class="qcard" aria-labelledby="qtitle">
          <div class="qmeta">
            <span><b>${esc(q.id)}</b></span><span>${TYPE_LABEL[q.type]}</span><span>${plural(q.points, 'point')}</span>
            ${sec ? `<span>${esc(sec.id)} · ${esc(sec.name)}</span>` : ''}
            ${q.suggested_minutes ? `<span>~${q.suggested_minutes} min</span>` : ''}
          </div>
          <h2 class="qtitle" id="qtitle">${q.title ? esc(q.title) : `Question ${qi + 1}`}</h2>
          <div class="prompt">${renderMd(q.prompt)}</div>
          ${answerHtml}
        </article>
        <div class="actions">
          <button type="button" class="btn" id="prev" ${qi === 0 ? 'disabled' : ''}>← Previous</button>
          <button type="button" class="btn" id="next" ${qi === ids.length - 1 ? 'disabled' : ''}>Next →</button>
          <button type="button" class="btn" id="flag" aria-pressed="${!!S.flagged[q.id]}">${S.flagged[q.id] ? '⚑ Flagged' : '⚐ Flag for review'}</button>
          <span class="spacer"></span>
          <span class="savedat" id="savedat"></span>
          <button type="button" class="btn danger" id="finish">${finishLabel}</button>
        </div>
        <p class="foot"><button type="button" class="linkish" id="abandon">Abandon this attempt</button></p>
      </main>`;

    // Restore text answers through the DOM so any characters are preserved exactly.
    const ta = $('#ans');
    if (ta) {
      ta.value = S.answers[q.id] || '';
      const upd = () => { $('#count').textContent = ta.value.length ? `${ta.value.length} chars` : ''; };
      upd();
      ta.addEventListener('input', () => { setAnswer(q.id, ta.value); upd(); });
      if (isCodeType(q)) enableTabKey(ta);
    }
    $$('input[name=opt]').forEach(r => r.addEventListener('change', () => {
      setAnswer(q.id, S.optionOrder[q.id][+r.value]);
    }));

    $('#prev').addEventListener('click', () => goTo(qi - 1));
    $('#next').addEventListener('click', () => goTo(qi + 1));
    $('#flag').addEventListener('click', () => {
      S.flagged[q.id] = !S.flagged[q.id];
      if (!S.flagged[q.id]) delete S.flagged[q.id];
      const b = $('#flag');
      b.setAttribute('aria-pressed', String(!!S.flagged[q.id]));
      b.textContent = S.flagged[q.id] ? '⚑ Flagged' : '⚐ Flag for review';
      refreshNav(); save();
    });
    $('#finish').addEventListener('click', onFinishClick);
    $('#abandon').addEventListener('click', abandonAttempt);
    $$('.qn').forEach(b => b.addEventListener('click', () => goTo(+b.dataset.i)));
    $$('.ptab[data-part]').forEach(b => b.addEventListener('click', () => switchPart(+b.dataset.part)));

    refreshNav();
    updateTimerUI();
    // After moving to another question, put focus on its heading so keyboard
    // and screen-reader users land at the top of the new question.
    const title = $('#qtitle');
    title.setAttribute('tabindex', '-1');
    if (opts.focus === 'title') title.focus({ preventScroll: true });
  }

  function refreshNav() {
    const pid = curPartId(), ids = S.order[pid];
    $$('.qn').forEach((b, i) => {
      const id = ids[i];
      const ans = isAnswered(id), fl = !!S.flagged[id];
      b.classList.toggle('answered', ans);
      b.classList.toggle('flagged', fl);
      b.setAttribute('aria-label', `Question ${i + 1}${ans ? ', answered' : ', not answered'}${fl ? ', flagged for review' : ''}`);
    });
    const p = $('#progress');
    if (p) p.textContent = `${ids.filter(isAnswered).length} of ${ids.length} answered`;
  }

  function setAnswer(qid, value) {
    if (typeof value === 'string' && value.trim() === '' && !(qid in S.answers)) return;
    S.answers[qid] = value;
    refreshNav();
    saveSoon();
  }

  function goTo(i) {
    const pid = curPartId(), n = S.order[pid].length;
    if (i < 0 || i >= n) return;
    S.qpos[pid] = i;
    save();
    renderExam({ focus: 'title' });
    window.scrollTo({ top: 0 });
  }

  function switchPart(i) {
    if (S.mode !== 'total' || i === S.cursor.partIdx) return;
    tick();                         // settle time-spent on the part we are leaving
    S.cursor.partIdx = i;
    save(); renderExam({ focus: 'title' });
    window.scrollTo({ top: 0 });
  }

  async function onFinishClick() {
    const scopeIds = S.mode === 'total' ? S.parts.flatMap(id => S.order[id]) : S.order[curPartId()];
    const unanswered = scopeIds.filter(id => !isAnswered(id)).length;
    const flagged = scopeIds.filter(id => S.flagged[id]).length;
    const lastPart = S.cursor.partIdx === S.parts.length - 1;
    const submitting = S.mode === 'total' || lastPart;
    const lines = [
      unanswered ? `<strong>${plural(unanswered, 'question')}</strong> still unanswered.` : 'Every question has an answer.',
      flagged ? `${plural(flagged, 'question')} flagged for review.` : '',
      submitting ? 'After submitting you cannot change your answers.' : `Part ${curPartId()} will lock. You cannot come back to it.`,
    ].filter(Boolean);
    tick();
    const ok = await confirmDialog({
      title: submitting ? 'Submit the exam?' : `Finish Part ${curPartId()}?`,
      body: lines.map(l => `<p>${l}</p>`).join(''),
      okLabel: submitting ? 'Submit' : 'Finish part', danger: true,
    });
    if (!ok || !S || S.phase !== 'active') return;
    if (submitting) finishExam('manual'); else endPart(S.cursor.partIdx, 'manual');
  }

  /* Tab-key support for code boxes. Esc then Tab leaves the box, so keyboard
   * users are never trapped. */
  function enableTabKey(ta) {
    let escaped = false;
    const INDENT = '    ';
    const insert = (text) => {
      ta.focus();
      if (!document.execCommand || !document.execCommand('insertText', false, text)) {
        ta.setRangeText(text, ta.selectionStart, ta.selectionEnd, 'end');
        ta.dispatchEvent(new Event('input', { bubbles: true }));
      }
    };
    ta.addEventListener('keydown', e => {
      if (e.key === 'Escape') { escaped = true; return; }
      if (e.key !== 'Tab' || e.ctrlKey || e.altKey || e.metaKey) { escaped = false; return; }
      if (escaped) { escaped = false; return; }
      e.preventDefault();
      const { selectionStart: a, selectionEnd: b, value } = ta;
      const multi = value.slice(a, b).includes('\n');
      if (!e.shiftKey && !multi) { insert(INDENT); return; }
      // indent or outdent every selected line
      const start = value.lastIndexOf('\n', a - 1) + 1;
      let end = value.indexOf('\n', b); if (end === -1) end = value.length;
      const block = value.slice(start, end);
      const next = block.split('\n').map(l => e.shiftKey ? l.replace(/^( {1,4}|\t)/, '') : INDENT + l).join('\n');
      ta.setSelectionRange(start, end);
      insert(next);
      ta.setSelectionRange(start, start + next.length);
    });
  }

  /* ---------- grading, results, downloads and attempt history ---------- */

  const isValidGrade = (value, max) => Number.isFinite(value) && value >= 0 &&
    value <= max && Math.abs(value * 2 - Math.round(value * 2)) < 1e-8;

  function scoreQuestion(q, session = S) {
    if (q.type === 'multiple_choice') return session.answers[q.id] === q.correct ? q.points : 0;
    const grade = session.grades && session.grades[q.id];
    return isValidGrade(grade, q.points) ? grade : 0;
  }

  function createSummary(session = S) {
    const partScores = {};
    const questionScores = {};
    for (const pid of session.parts) {
      const questions = DATA.questions.filter(q => q.part === pid);
      let score = 0;
      for (const q of questions) {
        const earned = scoreQuestion(q, session);
        questionScores[q.id] = { earned, possible: q.points };
        score += earned;
      }
      partScores[pid] = { score, possible: P[pid].points, percent: score / P[pid].points * 100, spentMs: session.partState[pid].spentMs };
    }
    const score = Object.values(partScores).reduce((n, part) => n + part.score, 0);
    const possible = Object.values(partScores).reduce((n, part) => n + part.possible, 0);
    const weakest = session.parts.map(pid => ({ id: pid, name: P[pid].name, ...partScores[pid] }))
      .sort((a, b) => a.percent - b.percent || a.id.localeCompare(b.id));
    return { score, possible, percent: possible ? score / possible * 100 : 0, partScores, questionScores, weakest };
  }

  function historyEntry(session = S) {
    const summary = createSummary(session);
    return {
      id: session.id,
      dataHash: session.dataHash,
      gradedAt: session.gradedAt || now(),
      seed: session.seed,
      mode: session.mode,
      parts: session.parts.slice(),
      answers: { ...session.answers },
      grades: { ...session.grades },
      order: JSON.parse(JSON.stringify(session.order)),
      optionOrder: JSON.parse(JSON.stringify(session.optionOrder)),
      partScores: summary.partScores,
      questionScores: summary.questionScores,
      score: summary.score,
      possible: summary.possible,
      percent: summary.percent,
    };
  }

  function persistHistoryEntry() {
    if (!S || S.status !== 'graded' || S.historySaved) return !!S?.historySaved;
    const attempts = readHistory();
    if (!attempts) return false;
    if (attempts.some(attempt => attempt.id === S.id)) {
      S.historySaved = true;
      save();
      return true;
    }
    const saved = writeHistory(attempts.concat(historyEntry()));
    if (saved) {
      S.historySaved = true;
      save();
    }
    return saved;
  }

  function ungradedQuestionIds() {
    return S.parts.flatMap(pid => DATA.questions
      .filter(q => q.part === pid && q.type !== 'multiple_choice' && !isValidGrade(S.grades[q.id], q.points))
      .map(q => q.id));
  }

  function finishGrading(treatRemainingAsZero = false) {
    const missing = ungradedQuestionIds();
    if (missing.length && !treatRemainingAsZero) return;
    if (treatRemainingAsZero) for (const qid of missing) S.grades[qid] = 0;
    S.status = 'graded';
    S.gradedAt = S.gradedAt || now();
    S.historySaved = false;
    save();
    persistHistoryEntry();
    renderSubmitted();
  }

  function gradePartsHtml(part) {
    const pieces = [];
    if (part.grading_scheme) pieces.push(`<section><h4>Part grading scheme</h4>${renderMd(part.grading_scheme)}</section>`);
    if (part.grading_notes && part.grading_notes.length) {
      pieces.push(`<section><h4>Part grading notes</h4>${renderMd(part.grading_notes.map(note => '- ' + note).join('\n'))}</section>`);
    }
    return pieces.join('');
  }

  function renderReviewQuestion(q, part) {
    const answer = S.answers[q.id];
    if (q.type === 'multiple_choice') {
      const correct = typeof answer === 'string' && answer === q.correct;
      return `<article class="review-q" id="review-${esc(q.id)}">
        <div class="qmeta"><b>${esc(q.id)}</b><span>multiple choice</span><span>${plural(q.points, 'point')}</span></div>
        <h3>${esc(q.title || q.id)}</h3><div class="prompt">${renderMd(q.prompt)}</div>
        <div class="review-columns">
          <section><h4>Your answer</h4>${answer ? renderMd(answer) : '<p class="empty-answer">No answer</p>'}</section>
          <section><h4>Correct answer</h4>${renderMd(q.correct || '')}<p class="mark ${correct ? 'good' : 'bad'}">${correct ? `Correct · ${q.points} / ${q.points} points` : `Incorrect · 0 / ${q.points} points`}</p></section>
        </div>
        ${q.explanation ? `<section class="review-extra"><h4>Explanation</h4>${renderMd(q.explanation)}</section>` : ''}
      </article>`;
    }

    const grade = isValidGrade(S.grades[q.id], q.points) ? S.grades[q.id] : '';
    const model = q.model_answer ? renderMd(q.model_answer) : '<p class="empty-answer">No model answer is available for this question.</p>';
    const rubric = q.rubric || part.rubric_each;
    return `<article class="review-q" id="review-${esc(q.id)}">
      <div class="qmeta"><b>${esc(q.id)}</b><span>${esc(TYPE_LABEL[q.type])}</span><span>${plural(q.points, 'point')}</span></div>
      <h3>${esc(q.title || q.id)}</h3><div class="prompt">${renderMd(q.prompt)}</div>
      <div class="review-columns">
        <section><h4>Your answer</h4>${answer ? renderMd(answer) : '<p class="empty-answer">No answer</p>'}</section>
        <section><h4>Model answer and grading hints</h4>${model}</section>
      </div>
      ${rubric ? `<section class="review-extra"><h4>Question rubric</h4>${renderMd(rubric)}</section>` : ''}
      ${gradePartsHtml(part)}
      <div class="self-grade">
        <label for="grade-${esc(q.id)}">Your score (0–${q.points}, whole or half points)</label>
        <div><input class="grade-input" id="grade-${esc(q.id)}" data-grade="${esc(q.id)}" type="number" min="0" max="${q.points}" step="0.5" inputmode="decimal" value="${grade}" aria-describedby="grade-error-${esc(q.id)}">
          <span> / ${q.points}</span></div>
        <p class="grade-error" id="grade-error-${esc(q.id)}" aria-live="polite"></p>
      </div>
    </article>`;
  }

  function updateGradeProgress() {
    const missing = ungradedQuestionIds().length;
    const progress = $('#grading-progress');
    if (progress) progress.textContent = missing ? `${plural(missing, 'question')} still ungraded` : 'All questions are graded';
    const finish = $('#finish-grading');
    if (finish) finish.disabled = missing > 0;
    const zero = $('#zero-ungraded');
    if (zero) zero.hidden = missing === 0;
  }

  function renderGradingReview() {
    const count = ungradedQuestionIds().length;
    const groups = S.parts.map(pid => {
      const part = P[pid];
      const questions = DATA.questions.filter(q => q.part === pid);
      return `<section class="review-part"><h2>Part ${pid}: ${esc(part.name)}</h2>${questions.map(q => renderReviewQuestion(q, part)).join('')}</section>`;
    }).join('');
    app.innerHTML = `<div class="wrap">
      ${publicNav()}
      <header class="result-head">
        <p class="eyebrow">review and self-grade</p>
        <h1>Exam submitted${S.submitReason === 'time' ? ': time ran out' : ''}</h1>
        <p class="meta-line">seed <code>${esc(S.seed)}</code> · ${S.mode === 'total' ? 'one total timer' : 'per-part timers'}</p>
      </header>
      <div class="review-intro">
        <p><strong>Self-grading:</strong> award yourself points for every non-multiple-choice question using the model answer, rubric and grading notes. Multiple-choice answers are graded automatically. Your final score stays hidden until all questions are graded, or you choose to score the rest as zero.</p>
        <p class="grading-progress" id="grading-progress" role="status">${count ? `${plural(count, 'question')} still ungraded` : 'All questions are graded'}</p>
      </div>
      ${groups}
      <div class="grading-actions">
        <button type="button" class="btn primary" id="finish-grading" ${count ? 'disabled' : ''}>Finish grading and show results</button>
        <button type="button" class="btn danger" id="zero-ungraded" ${count ? '' : 'hidden'}>Treat remaining as zero and finish</button>
        <button type="button" class="linkish" id="abandon">Discard this attempt</button>
        <span class="savedat" id="savedat"></span>
      </div>
      <p class="foot">Grades are saved in this browser as you type. Nothing is uploaded.</p>
    </div>`;

    $$('[data-grade]').forEach(input => input.addEventListener('input', () => {
      const qid = input.dataset.grade, q = Q[qid], raw = input.value.trim();
      const value = raw === '' ? NaN : Number(raw);
      const valid = isValidGrade(value, q.points);
      const error = document.getElementById(`grade-error-${qid}`);
      input.setAttribute('aria-invalid', String(raw !== '' && !valid));
      if (!raw || valid) {
        delete S.grades[qid];
        if (valid) S.grades[qid] = value;
        error.textContent = '';
      } else {
        delete S.grades[qid];
        error.textContent = `Enter 0 to ${q.points} in whole or half-point steps.`;
      }
      S.status = 'grading';
      save();
      updateGradeProgress();
    }));
    $('#finish-grading').addEventListener('click', () => finishGrading(false));
    $('#zero-ungraded').addEventListener('click', async () => {
      const countNow = ungradedQuestionIds().length;
      if (!countNow) return;
      const ok = await confirmDialog({
        title: 'Score the remaining questions as zero?',
        body: `<p>${plural(countNow, 'ungraded question')} will receive zero points. This will complete grading and save the result to local history.</p>`,
        okLabel: 'Set remaining to zero', danger: true,
      });
      if (ok && S && S.phase === 'submitted') finishGrading(true);
    });
    $('#abandon').addEventListener('click', abandonAttempt);
    bindPublicNav();
  }

  function localFileStamp(date = new Date()) {
    const pad = n => String(n).padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}-${pad(date.getHours())}${pad(date.getMinutes())}`;
  }

  function resultPayload() {
    const summary = createSummary();
    const questionDetails = DATA.questions.filter(q => S.parts.includes(q.part)).map(q => ({
      id: q.id, part: q.part, type: q.type, points: q.points,
      answer: S.answers[q.id] ?? null,
      correct: q.type === 'multiple_choice' ? q.correct : undefined,
      score: summary.questionScores[q.id].earned,
      maxScore: q.points,
    }));
    return {
      formatVersion: 1,
      exam: DATA.meta.title,
      dataHash: S.dataHash,
      attemptId: S.id,
      submittedAt: S.submittedAt,
      gradedAt: S.gradedAt,
      seed: S.seed,
      mode: S.mode,
      partsTaken: S.parts.slice(),
      totalScore: summary.score,
      totalPossible: summary.possible,
      percentage: summary.percent,
      partScores: summary.partScores,
      answers: { ...S.answers },
      grades: { ...S.grades },
      questionDetails,
      spentMs: Object.fromEntries(S.parts.map(pid => [pid, S.partState[pid].spentMs])),
      questionOrder: JSON.parse(JSON.stringify(S.order)),
      optionOrder: JSON.parse(JSON.stringify(S.optionOrder)),
    };
  }

  function resultMarkdown() {
    const summary = createSummary();
    const payload = resultPayload();
    const parts = S.parts.map(pid => `| ${pid} | ${esc(P[pid].name)} | ${summary.partScores[pid].score} / ${summary.partScores[pid].possible} (${summary.partScores[pid].percent.toFixed(1)}%) | ${fmtClock(S.partState[pid].spentMs)} |`);
    const weak = summary.weakest.slice(0, 3).map(p => `- Part ${p.id}: ${p.name} (${p.percent.toFixed(1)}%)`).join('\n');
    const wrong = DATA.questions.filter(q => S.parts.includes(q.part) && summary.questionScores[q.id].earned * 2 < q.points)
      .map(q => `- ${q.id}: ${summary.questionScores[q.id].earned} / ${q.points} points`);
    return `# ${DATA.meta.title} — results

- Date graded: ${new Date(S.gradedAt).toLocaleString()}
- Parts taken: ${S.parts.join(', ')}
- Total: ${summary.score} / ${summary.possible} (${summary.percent.toFixed(1)}%)
- Seed: ${S.seed}
- Timer mode: ${S.mode === 'total' ? 'one total timer' : 'per-part timers'}

| Part | Topic | Score | Time used |
| --- | --- | ---: | ---: |
${parts.join('\n')}

## Weakest parts

${weak || 'No parts were taken.'}

## Questions below 50% (including unanswered)

${wrong.length ? wrong.join('\n') : 'None.'}

Results are private and stored only where you choose to keep this downloaded file.`;
  }

  function downloadResult(format) {
    const notice = $('#download-notice');
    try {
      const stamp = localFileStamp(new Date(S.gradedAt));
      const isJson = format === 'json';
      const contents = isJson ? JSON.stringify(resultPayload(), null, 2) : resultMarkdown();
      const blob = new Blob([contents], { type: isJson ? 'application/json' : 'text/markdown' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `results-${stamp}.${format}`;
      document.body.append(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      notice.textContent = 'The download was requested by your browser. Move it into a local results/ folder if you want to keep it; do not commit or upload it.';
    } catch (e) {
      notice.textContent = `Could not create the download: ${e.message}`;
    }
  }

  function renderFinalResults() {
    persistHistoryEntry();
    const summary = createSummary();
    const allParts = S.parts.length === DATA.parts.length && DATA.parts.every(p => S.parts.includes(p.id));
    const band = allParts ? DATA.score_bands.find(item => Math.floor(summary.score) >= item.min && Math.floor(summary.score) <= item.max) : null;
    const rows = S.parts.map(pid => `<tr><td>Part ${pid}</td><td>${esc(P[pid].name)}</td><td class="num">${summary.partScores[pid].score} / ${summary.partScores[pid].possible} (${summary.partScores[pid].percent.toFixed(1)}%)</td><td class="num">${fmtClock(S.partState[pid].spentMs)}</td><td class="num">${fmtMinutes(P[pid].minutes)}</td></tr>`).join('');
    const weakest = summary.weakest.slice(0, 3).map(p => `<li>Part ${p.id}: ${esc(p.name)} — ${p.percent.toFixed(1)}%</li>`).join('');
    const allTakenMsg = summary.weakest.length < 3 ? `<p class="meta-line">Only ${plural(summary.weakest.length, 'part')} taken, so fewer than three weakest parts can be listed.</p>` : '';
    app.innerHTML = `<div class="wrap">
      ${publicNav()}
      <header class="result-head">
        <p class="eyebrow">graded</p><h1>Your results</h1>
        <p class="meta-line">${new Date(S.gradedAt).toLocaleString()} · seed <code>${esc(S.seed)}</code> · ${S.mode === 'total' ? 'one total timer' : 'per-part timers'}</p>
      </header>
      <section class="score-card">
        <h2>${summary.score} / ${summary.possible} points <span>(${summary.percent.toFixed(1)}%)</span></h2>
        ${allParts ? `<p><strong>${esc(band?.label || 'Score band')}:</strong> ${esc(band?.message || '')}</p>` : '<p>This was a partial selection of parts, so this percentage cannot be placed on the 400-point score-band scale.</p>'}
      </section>
      ${historyProblem ? `<p class="notice" role="alert">${esc(historyProblem)} Your graded session is still saved; export it with the results download.</p>` : (!S.historySaved ? '<p class="notice" role="alert">This attempt could not be added to history. Check browser storage and try again from History.</p>' : '')}
      <h2 class="section-title">Scores and time used</h2>
      <div class="table-scroll"><table class="tbl"><thead><tr><th>Part</th><th>Topic</th><th class="num">Score</th><th class="num">Time used</th><th class="num">Budget</th></tr></thead><tbody>${rows}</tbody></table></div>
      <h2 class="section-title">Three weakest parts by percentage</h2>
      <ol class="weakest">${weakest}</ol>${allTakenMsg}
      <p class="notice">Results stay on this device unless you download them. The browser cannot write directly into your project folder. Downloads are private; do not commit or upload them.</p>
      <div class="actions">
        <button type="button" class="btn primary" id="download-json">Download detailed JSON</button>
        <button type="button" class="btn" id="download-md">Download summary Markdown</button>
        <button type="button" class="btn" id="new-attempt">Start new attempt</button>
        <span class="spacer"></span><button type="button" class="linkish" id="abandon">Discard this attempt</button>
      </div>
      <p id="download-notice" class="download-notice" role="status" aria-live="polite"></p>
    </div>`;
    $('#download-json').addEventListener('click', () => downloadResult('json'));
    $('#download-md').addEventListener('click', () => downloadResult('md'));
    $('#new-attempt').addEventListener('click', () => {
      S = null; writeSession(null); renderSetup();
      window.scrollTo({ top: 0 });
    });
    $('#abandon').addEventListener('click', abandonAttempt);
    bindPublicNav();
  }

  function renderSubmitted() {
    if (S.status === 'graded') return renderFinalResults();
    return renderGradingReview();
  }

  async function abandonAttempt() {
    const submitted = S && S.phase === 'submitted';
    const ok = await confirmDialog({
      title: submitted ? 'Discard this attempt?' : 'Abandon this attempt?',
      body: submitted
        ? '<p>Any ungraded points or results that you have not downloaded will be lost. This only removes the current session; it never deletes or changes attempt history.</p>'
        : '<p>Your answers for this attempt will be deleted from this browser. Previously saved attempt history is not affected. This cannot be undone.</p>',
      okLabel: submitted ? 'Discard attempt' : 'Abandon', danger: true,
    });
    if (!ok) return;
    S = null; writeSession(null); renderSetup();
  }

  function dateLabel(timestamp) {
    return timestamp ? new Date(timestamp).toLocaleString() : 'Unknown date';
  }

  function historyChart(pid, attempts) {
    const points = attempts.filter(a => a.parts.includes(pid) && a.partScores?.[pid])
      .slice().sort((a, b) => a.gradedAt - b.gradedAt);
    if (!points.length) return '<p class="empty-answer">No attempts for this part yet.</p>';
    const width = 640, height = 180, left = 38, right = 16, top = 14, bottom = 28;
    const plotW = width - left - right, plotH = height - top - bottom;
    const xy = points.map((a, i) => ({
      x: points.length === 1 ? left + plotW / 2 : left + i * plotW / (points.length - 1),
      y: top + plotH * (1 - a.partScores[pid].percent / 100),
    }));
    const grid = [0, 50, 100].map(percent => {
      const y = top + plotH * (1 - percent / 100);
      return `<line x1="${left}" y1="${y}" x2="${width - right}" y2="${y}" class="chart-grid"/><text x="${left - 6}" y="${y + 4}" text-anchor="end" class="chart-label">${percent}%</text>`;
    }).join('');
    const line = xy.length > 1 ? `<polyline points="${xy.map(p => `${p.x},${p.y}`).join(' ')}" class="chart-line"/>` : '';
    const circles = xy.map((p, i) => `<circle cx="${p.x}" cy="${p.y}" r="5" class="chart-dot"><title>${esc(dateLabel(points[i].gradedAt))}: ${points[i].partScores[pid].score} / ${points[i].partScores[pid].possible}</title></circle>`).join('');
    const rows = points.map(a => `<tr><td>${esc(dateLabel(a.gradedAt))}</td><td class="num">${a.partScores[pid].score} / ${a.partScores[pid].possible}</td><td class="num">${a.partScores[pid].percent.toFixed(1)}%</td></tr>`).join('');
    return `<figure class="chart-wrap"><svg class="score-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Part ${pid} score over time, percentage of points earned">
      ${grid}<line x1="${left}" y1="${top + plotH}" x2="${width - right}" y2="${top + plotH}" class="chart-axis"/>${line}${circles}
    </svg><figcaption>Each point is one graded attempt; the table is the accessible text equivalent.</figcaption></figure>
    <div class="table-scroll"><table class="tbl"><thead><tr><th>Date</th><th class="num">Score</th><th class="num">Percent</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }

  function validHistoryAttempt(attempt) {
    return attempt && typeof attempt.id === 'string' && attempt.id.length > 0 &&
      typeof attempt.dataHash === 'string' && Array.isArray(attempt.parts) &&
      attempt.parts.length > 0 && attempt.parts.every(pid => !!P[pid]) &&
      Number.isFinite(attempt.gradedAt) && attempt.partScores &&
      attempt.parts.every(pid => attempt.partScores[pid] &&
        Number.isFinite(attempt.partScores[pid].score) &&
        Number.isFinite(attempt.partScores[pid].possible) &&
        Number.isFinite(attempt.partScores[pid].percent)) &&
      Number.isFinite(attempt.score) && Number.isFinite(attempt.possible) &&
      Number.isFinite(attempt.percent);
  }

  function exportHistory(attempts) {
    try {
      const blob = new Blob([JSON.stringify({ formatVersion: HISTORY_VERSION, attempts }, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `swe-exam-history-${localFileStamp()}.json`;
      document.body.append(link); link.click(); link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      $('#history-notice').textContent = 'History export downloaded. Keep a private backup: browser data can be lost if local storage is cleared.';
    } catch (e) {
      $('#history-notice').textContent = `Could not export history: ${e.message}`;
    }
  }

  async function importHistory(file, currentAttempts) {
    const notice = $('#history-notice');
    let data;
    try {
      data = JSON.parse(await file.text());
    } catch (e) {
      notice.textContent = `Could not read the selected JSON file: ${e.message}`;
      return;
    }
    if (!data || data.formatVersion !== HISTORY_VERSION || !Array.isArray(data.attempts)) {
      notice.textContent = `This is not a supported history export (expected format version ${HISTORY_VERSION}).`;
      return;
    }
    if (!data.attempts.every(validHistoryAttempt)) {
      notice.textContent = 'The history file contains an invalid attempt record. Nothing was imported.';
      return;
    }
    const known = new Set(currentAttempts.map(attempt => attempt.id));
    const added = [];
    for (const attempt of data.attempts) {
      if (known.has(attempt.id)) continue;
      known.add(attempt.id);
      added.push(attempt);
    }
    const skipped = data.attempts.length - added.length;
    const ok = await confirmDialog({
      title: 'Import attempt history?',
      body: `<p>${plural(added.length, 'attempt')} will be added. ${plural(skipped, 'duplicate attempt')} will be skipped by id; no existing attempt will be overwritten.</p>`,
      okLabel: 'Import history',
    });
    if (!ok) return;
    const saved = writeHistory(currentAttempts.concat(added));
    notice.textContent = saved
      ? `Imported ${plural(added.length, 'attempt')}; skipped ${plural(skipped, 'duplicate')}.`
      : historyProblem;
    if (saved) renderHistory(notice.textContent);
  }

  function renderHistory(noticeText = '') {
    const attempts = readHistory();
    const usable = attempts || [];
    const sorted = usable.slice().sort((a, b) => b.gradedAt - a.gradedAt);
    const warnings = usable.filter(a => a.dataHash !== DATA.meta.source_sha256).length;
    const attemptRows = sorted.length ? sorted.map(a => `<tr>
      <td>${esc(dateLabel(a.gradedAt))}</td><td>${esc(a.parts.join(', '))}</td>
      <td class="num">${Number(a.score).toFixed(1)} / ${Number(a.possible).toFixed(1)}</td>
      <td class="num">${Number(a.percent).toFixed(1)}%</td><td>${a.dataHash === DATA.meta.source_sha256 ? 'Current exam' : 'Different exam version'}</td>
    </tr>`).join('') : '<tr><td colspan="5">No graded attempts have been saved yet.</td></tr>';
    const charts = DATA.parts.map(p => `<section class="history-part"><h3>Part ${p.id}: ${esc(p.name)}</h3>${historyChart(p.id, usable)}</section>`).join('');
    app.innerHTML = `<div class="wrap">
      ${publicNav('history')}
      <header class="result-head"><p class="eyebrow">local archive</p><h1>Attempt history</h1>
        <p class="meta-line">History lives only in this browser. Clearing browser data can erase it, so export a private backup.</p>
      </header>
      ${historyProblem ? `<p class="notice" role="alert">${esc(historyProblem)} Do not import until the existing history is recoverable.</p>` : ''}
      ${warnings ? `<p class="notice" role="status">${plural(warnings, 'attempt')} came from a different exam version. Its saved scores are preserved but may not match the current questions.</p>` : ''}
      ${noticeText ? `<p class="notice" role="status">${esc(noticeText)}</p>` : ''}
      <div class="actions history-actions">
        <button type="button" class="btn" id="export-history" ${attempts === null ? 'disabled' : ''}>Export all history</button>
        <label class="btn file-button" for="import-history">Import history</label>
        <input id="import-history" class="visually-hidden" type="file" accept="application/json,.json" ${attempts === null ? 'disabled' : ''}>
      </div>
      <p class="download-notice" id="history-notice" role="status" aria-live="polite"></p>
      <h2 class="section-title">Graded attempts</h2>
      <div class="table-scroll"><table class="tbl"><thead><tr><th>Date</th><th>Parts</th><th class="num">Score</th><th class="num">Percent</th><th>Exam version</th></tr></thead><tbody>${attemptRows}</tbody></table></div>
      <h2 class="section-title">Scores over time by part</h2>
      <p class="meta-line">Each chart groups retakes of the same part; points are shown as a percentage to compare attempts consistently.</p>
      ${charts}
      <p class="foot">No history or scores are uploaded. Export files are private backups; do not commit or upload them.</p>
    </div>`;
    $('#export-history').addEventListener('click', () => exportHistory(usable));
    $('#import-history').addEventListener('change', async event => {
      const file = event.target.files?.[0];
      if (file) await importHistory(file, usable);
      event.target.value = '';
    });
    bindPublicNav();
  }

  /* ================================================================
   * Boot
   * ================================================================ */

  function boot() {
    const saved = loadSession();
    if (saved && saved.v === SESSION_VERSION) {
      if (saved.dataHash !== DATA.meta.source_sha256) {
        app.innerHTML = `<div class="wrap"><div class="card"><h1>Saved attempt does not match this exam</h1>
          <p>The exam file changed since this attempt started, so its answers cannot be trusted. Discard it to start fresh.</p>
          <button type="button" class="btn danger" id="discard">Discard saved attempt</button></div></div>`;
        $('#discard').addEventListener('click', () => { writeSession(null); S = null; render(); });
        return;
      }
      S = migrateSession(saved);
    }
    render();
    tick();                                   // settle any time that passed while the page was closed
    setInterval(tick, 250);
    document.addEventListener('visibilitychange', () => { tick(); if (document.visibilityState === 'hidden') save(); });
    window.addEventListener('pagehide', () => { if (S) { tick(); save(); } });
  }

  boot();
})();
